//! The regions that can be downloaded: the US states, the District of Columbia,
//! Puerto Rico and the US Virgin Islands; the Canadian provinces and territories
//! (Nunavut in two halves); Mexico, whole and by state; and every region elsewhere
//! that Geofabrik publishes a Shortbread package for, except those whose outline
//! crosses the 180th meridian. Maps come from Geofabrik or, for regions Geofabrik
//! does not publish on their own, from this project's `regions` release.
//! The table is generated by `tools/make-regions.py`.
use crate::package::Region;

#[path = "regions_data.rs"]
mod data;

pub use data::ALL;

/// The region with this ID (`us-il`), if it is in the catalog.
pub fn find(id: &str) -> Option<&'static Region> {
    ALL.iter().find(|r| r.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_is_consistent() {
        assert!(ALL.len() > 300, "{}", ALL.len());
        let north_america = ALL.iter().filter(|r| r.continent == "North America");
        assert_eq!(
            north_america.filter(|r| r.country != "Greenland").count(),
            100
        );
        assert_eq!(find("us-il"), Some(&crate::package::ILLINOIS));
        // Alaska and Canada are built for the app (tools/regions-build/build_shortbread.py).
        let alaska = find("us-ak").unwrap();
        assert!(alaska.package_url.contains("/releases/download/regions/"));
        assert!(
            alaska
                .extras_url
                .starts_with("https://download.geofabrik.de/")
        );
        assert_eq!(ALL.iter().filter(|r| r.id.starts_with("ca-")).count(), 14);
        assert_eq!(find("ca-qc").unwrap().name, "Quebec");
        let mut ids: Vec<_> = ALL.iter().map(|r| r.id).collect();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids.len(), ALL.len());
        for r in &ALL {
            assert!(
                r.id.bytes()
                    .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-'),
                "{}",
                r.id
            );
            assert!(!r.country.is_empty() && !r.continent.is_empty(), "{}", r.id);
            assert!(r.package_url.ends_with("-shortbread-1.0.mbtiles"));
            assert!(r.extras_url.ends_with("-latest.osm.pbf"));
            assert!(r.package_bytes > 0 && r.extras_bytes > 0 && r.terrain_bytes > 0);
            let o = r.outer;
            assert!(o.west < o.east && o.south < o.north, "{}", r.name);
            for (lon, lat) in r.required_points {
                assert!((o.west..=o.east).contains(lon) && (o.south..=o.north).contains(lat));
            }
        }
        assert_eq!(find("us-dc").unwrap().name, "District of Columbia");
        assert_eq!(find("us-vi").unwrap().name, "US Virgin Islands");
        let mexico = find("mx").unwrap();
        assert_eq!(mexico.name, "All of Mexico");
        // The states come from this project's releases (tools/regions-build).
        let states: Vec<_> = ALL.iter().filter(|r| r.id.starts_with("mx-")).collect();
        assert_eq!(states.len(), 32);
        for r in states {
            assert!(r.package_url.starts_with(
                "https://github.com/ianrastall/offline-maps/releases/download/regions/"
            ));
            assert!(r.extras_url.ends_with(&format!("/{}-latest.osm.pbf", r.id)));
        }
        assert_eq!(find("mx-cmx").unwrap().name, "Mexico City");
        assert!(
            mexico
                .package_url
                .starts_with("https://download.geofabrik.de/north-america/mexico-")
        );
        assert_eq!(mexico.overlay_bytes, 0);
        // Outer boxes take in the raw extracts' header boxes, which reach beyond the
        // index outlines (measured 11 November 2026 by tools/extract-boxes.py).
        for (id, extract) in [
            ("mx", (-132.495, 9.080, -81.605, 32.721)),
            ("us-mi", (-90.420, 41.694, -79.047, 49.325)),
            ("us-ks", (-107.303, 33.401, -94.589, 40.007)),
            ("us-hi", (-179.848, 10.836, -137.523, 29.096)),
        ] {
            let o = find(id).unwrap().outer;
            let (w, s, e, n) = extract;
            assert!(
                o.west <= w && o.south <= s && e <= o.east && n <= o.north,
                "{id}"
            );
        }
    }
}
